const { readFileSync, writeFileSync, mkdirSync, copyFileSync } = require("node:fs");
const { join } = require("node:path");

const root = join(__dirname, "..");
const output = join(root, "FlowNote-Vault", ".obsidian", "plugins", "flownote-assistant");
const core = readFileSync(join(root, "src", "core.cjs"), "utf8");
const plugin = readFileSync(join(root, "src", "plugin.cjs"), "utf8");

mkdirSync(output, { recursive: true });
writeFileSync(join(output, "main.js"),
  "// Generated by scripts/build.cjs. Edit src/ and run npm run build.\n" +
  "const flowNoteCore = (() => {\nconst module = { exports: {} };\n" +
  core + "\nreturn module.exports;\n})();\n" +
  plugin.replace('require("./core.cjs")', "flowNoteCore"));
copyFileSync(join(root, "manifest.json"), join(output, "manifest.json"));
copyFileSync(join(root, "src", "styles.css"), join(output, "styles.css"));
